"""Snapping clock times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def check_step(step: int) -> None:
    """A step must be a positive whole number of minutes that divides an hour."""
    if not isinstance(step, int) or step <= 0 or 60 % step:
        raise ValueError(f"step must divide an hour evenly: {step!r}")

def snap_minute(minute: int, step: int) -> int:
    """Nearest multiple of step, with exact halves going up."""
    return (minute + step // 2) // step * step

def round_span(span: Span, step: int) -> Span:
    """Snap both ends. Raises ValueError if the span collapses to nothing."""
    check_step(step)
    return Span(snap_minute(span.start, step), snap_minute(span.end, step))

def format_duration(minutes: int) -> str:
    hours, rest = divmod(minutes, 60)
    return f"{hours}h {rest}m"

def span_label(span: Span) -> str:
    return f"{format_span(span)} ({format_duration(span.minutes)})"

def round_labels(spans: Iterable[Span], step: int) -> List[str]:
    """One label per span, such as 09:00-17:15 (8h 15m), in the input order."""
    check_step(step)
    return [span_label(round_span(item, step)) for item in spans]

