# owner: platform
import unittest

from hourglass.rounding import round_labels, round_span, snap_minute
from hourglass.models import Span

class SnapTests(unittest.TestCase):
    def test_rounds_to_nearest(self):
        self.assertEqual(snap_minute(7, 15), 0)
        self.assertEqual(snap_minute(8, 15), 15)

    def test_exact_half_goes_up(self):
        self.assertEqual(snap_minute(30, 60), 60)

    def test_collapsed_span_is_rejected(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 543), 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 14)]
        self.assertEqual(round_labels(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_keeps_order_and_handles_many(self):
        spans = [Span(600, 660), Span(0, 1440)]
        labels = round_labels(spans, 30)
        self.assertEqual(labels, ["10:00-11:00 (1h 0m)", "00:00-24:00 (24h 0m)"])

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90, 2.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels([Span(60, 120)], step)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(len(round_labels([Span(60, 180)], step)), 1)
